import { R, X, lesson, mcq, numeric, short } from './helpers';
import type { Lesson } from '@/lib/types';

/**
 * MICROCONTROLLERS - the EMBEDDED track's hands-on core.
 *
 * Everything here is verifiable on hardware costing under twenty dollars,
 * because firmware cannot be learned from a simulator alone: the failure modes
 * that teach the most (floating inputs, brownouts, bus lockups, timing races)
 * only appear on real silicon. Every lesson with a `hardware` tag says so
 * explicitly, and the planner will not schedule those exercises until you mark
 * yourself as having the parts.
 *
 * DAG: mcu-01 -> mcu-02 -> mcu-03 -> mcu-04 -> mcu-05 -> mcu-06 -> mcu-07
 *      -> mcu-08 -> mcu-09 -> mcu-10
 */
